from solution import fix_spaces
import re
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(text):
    # Obviously-correct model: each maximal run of ' ' maps to
    # '_' if len==1, '__' if len==2, '-' if len>=3; other chars unchanged.
    out = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] != ' ':
            out.append(text[i])
            i += 1
        else:
            j = i
            while j < n and text[j] == ' ':
                j += 1
            run = j - i
            if run <= 2:
                out.append('_' * run)
            else:
                out.append('-')
            i = j
    return ''.join(out)


# ---- concrete examples from spec ----

def test_example_no_spaces():
    assert fix_spaces("Example") == "Example"

def test_example_single_space():
    assert fix_spaces("Example 1") == "Example_1"

def test_example_leading_single_space():
    assert fix_spaces(" Example 2") == "_Example_2"

def test_example_mixed_runs():
    assert fix_spaces(" Example   3") == "_Example-3"


# ---- explicit boundary examples derived from spec ----

def test_empty_string():
    assert fix_spaces("") == ""

def test_single_space_becomes_underscore():
    assert fix_spaces(" ") == "_"

def test_two_spaces_become_two_underscores():
    assert fix_spaces("  ") == "__"

def test_three_spaces_become_dash():
    assert fix_spaces("   ") == "-"

def test_four_spaces_become_single_dash():
    assert fix_spaces("    ") == "-"

def test_many_spaces_become_single_dash():
    assert fix_spaces(" " * 10) == "-"

def test_two_runs_mixed():
    # 2 spaces -> __, 3 spaces -> -
    assert fix_spaces("a  b   c") == "a__b-c"

def test_leading_trailing_runs():
    assert fix_spaces("   a  ") == "-a__"
    assert fix_spaces("  a   ") == "__a-"

def test_only_underscores_and_dashes_unchanged():
    assert fix_spaces("a_b-c") == "a_b-c"
    assert fix_spaces("_-__--") == "_-__--"

def test_tab_and_newline_not_spaces():
    # Only ' ' is a space; other whitespace must be preserved.
    assert fix_spaces("a\tb") == "a\tb"
    assert fix_spaces("a\nb") == "a\nb"
    assert fix_spaces("a \tb") == "a_\tb"


# ---- properties ----

text_strategy = st.text(
    alphabet=st.sampled_from(["a", "B", " ", " ", "_", "-", "1", "!", "\t"]),
    max_size=20,
)

plain_strategy = st.text(
    alphabet=st.sampled_from(["a", "b", "X", "0", "!"]),
    max_size=10,
)

spaces_strategy = st.integers(min_value=0, max_value=10)


def test_property_no_spaces_remain():
    @given(text_strategy)
    def inner(text):
        assert ' ' not in fix_spaces(text)
    inner()

def test_property_equivalence_to_reference_model():
    @given(text_strategy)
    def inner(text):
        assert fix_spaces(text) == reference(text)
    inner()

def test_property_no_space_input_is_identity():
    @given(st.text(alphabet=st.sampled_from(["a", "b", "X", "0", "_", "-", "!", "\t", "\n"]), max_size=20))
    def inner(text):
        assume(' ' not in text)
        assert fix_spaces(text) == text
    inner()

def test_property_output_length_never_grows():
    @given(text_strategy)
    def inner(text):
        assert len(fix_spaces(text)) <= len(text)
    inner()

def test_property_output_length_equality_iff_no_long_run():
    @given(text_strategy)
    def inner(text):
        out = fix_spaces(text)
        has_long = re.search(r' {3,}', text) is not None
        if not has_long:
            assert len(out) == len(text)
        else:
            # each long run collapses by at least 2 chars
            assert len(out) < len(text)
    inner()

def test_property_idempotence():
    @given(text_strategy)
    def inner(text):
        once = fix_spaces(text)
        assert fix_spaces(once) == once
    inner()

def test_property_run_mapping_collapses_long_runs():
    @given(spaces_strategy, plain_strategy, plain_strategy)
    def inner(n, left, right):
        text = left + " " * n + right
        out = fix_spaces(text)
        if n == 0:
            assert out == left + right
        elif n == 1:
            assert out == left + "_" + right
        elif n == 2:
            assert out == left + "__" + right
        else:
            assert out == left + "-" + right
    inner()

def test_property_nonspace_chars_preserved_in_order():
    @given(text_strategy)
    def inner(text):
        out = fix_spaces(text)
        # Deleting '_' and '-' from output cannot be directly compared
        # when input already contains them, so use a projected check:
        # non-space, non-underscore, non-dash chars must appear unchanged and in order.
        # Use sentinel-free filtering with distinct alphabet.
        filtered_in = [c for c in text if c not in (' ', '_', '-')]
        # Expand output: '-' could hide spaces, '_' hides spaces, but other chars pass through.
        filtered_out = [c for c in out if c not in ('_', '-')]
        # If input had no '_'/'-', filtered_out must equal filtered_in exactly.
        if '_' not in text and '-' not in text:
            assert filtered_out == filtered_in
        else:
            # Otherwise filtered_in must be a subsequence of filtered_out in order
            # (since '_'/'-' in input are kept, never deleted).
            idx = 0
            for c in filtered_out:
                if idx < len(filtered_in) and c == filtered_in[idx]:
                    idx += 1
            # All non-special input chars must be found in order
            assert idx == len(filtered_in)
    inner()
